// Explicit W06 CLI lane: leave legacy Core/BLS/SEC code and reports intact.
if(process.argv.includes('--cnn-minute')){
 const {writeSync,existsSync}=await import('node:fs');
 const receipt={at:new Date().toISOString(),lane:'cnn-minute',status:'FAILED'};
 let core,hooks;
 const originalFetch=globalThis.fetch;
 try{
  if(process.argv.slice(2).length!==1)throw Error('CNN_MINUTE_SCOPE_STOP');
  const base=process.env.ZGMINI_PC_HOME??path.join(os.homedir(),'.zgmini','pc-writer');
  const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../..');
  const config=read(path.join(base,'config.json'));
  const source=execFileSync('git',['rev-parse','HEAD'],{cwd:root,encoding:'utf8',windowsHide:true}).trim();
  if(config.enabled!==true||config.collectionTarget!=='pc'||!/^[0-9a-f]{40}$/.test(source)||config.source!==source)
   throw Error('CNN_MINUTE_SOURCE_NOT_APPROVED');
  if(execFileSync('git',['status','--porcelain','--untracked-files=all','--','lib','worker','scripts/pc-writer'],{cwd:root,encoding:'utf8',windowsHide:true}).trim())
   throw Error('CNN_MINUTE_SOURCE_NOT_APPROVED');
  const dbFile=path.join(base,'storage','core.sqlite');
  if(!existsSync(dbFile))throw Error('CNN_MINUTE_CORE_DB_MISSING');
  core=localDatabase(dbFile);
  const env={DB:core,DB_CORE:core,ZGMINI_COMPUTE_TARGET:'pc'};
  hooks=installLocalRuntime(env);
  const quota=createQuotaFetch({base,originalFetch});
  globalThis.fetch=quota.fetch;
  const {collect}=await import('../../worker/feed-collectors/fear-greed.ts');
  const {refreshPublicFeeds,observeCnnCollector}=await import('../../worker/public-feed-refresh.mjs');
  const result=await refreshPublicFeeds({env,maxFeedsPerRun:1,cnnMinuteOnly:true,collectors:{'fear-greed':observeCnnCollector(collect)}});
  Object.assign(receipt,{status:result.status,attempted:result.attempted??0,feeds:result.feeds?.map(({key,status})=>({key,status}))});
 }catch(error){
  receipt.reason=/^CNN_MINUTE_[A-Z_]+$/.test(error?.message??'')?error.message:'CNN_MINUTE_COLLECTION_FAILED';
 }finally{
  globalThis.fetch=originalFetch;
  try{hooks?.deregister();}finally{core?.close();}
 }
 writeSync(1,JSON.stringify(receipt)+'\n');
 process.exit(['COMPLETE','PARTIAL','ALREADY_RUNNING'].includes(receipt.status)?0:1);
}

// Explicit CNN scope uses the existing collection and publication entries.
// No new scheduler, global Core lock, provider loop or Core checkpoint writes.
if(process.argv.includes('--cnn-minute')){
 if(process.argv.slice(2).length!==2||!process.argv.includes('--publish'))
  throw Error('CNN_MINUTE_CYCLE_SCOPE_STOP');
 const runChild=(name,args)=>{
  const child=spawnSync(process.execPath,[path.join(here,name),...args],
   {windowsHide:true,stdio:['ignore','pipe','pipe'],encoding:'utf8',timeout:5*60000});
  if(child.error||child.signal||!Number.isInteger(child.status))throw Error('CNN_MINUTE_CHILD_OUTCOME_UNKNOWN');
  let receipt;try{receipt=JSON.parse(child.stdout.trim().split(/\r?\n/).at(-1));}catch{throw Error('CNN_MINUTE_CHILD_RECEIPT_UNKNOWN');}
  if(child.status!==0&&receipt?.status!=='FAILED'&&receipt?.status!=='PARTIAL')
   throw Error('CNN_MINUTE_CHILD_OUTCOME_UNKNOWN');
  return receipt;
 };
 const {runCnnMinuteCycle}=await import('./collection-publication-policy.mjs');
 const report=await runCnnMinuteCycle({
  collect:()=>runChild('collect-local.mjs',['--cnn-minute']),
  publish:()=>runChild('run-local.mjs',['--cnn-minute','--publish']),
 });
 fs.writeSync(1,JSON.stringify(report)+'\n');
 process.exit(['COMPLETE','COMPLETE_WITH_COLLECTION_GAPS','SKIPPED_ACTIVE_COLLECTION'].includes(report.status)?0:1);
}

const ALPACA_LOCK_WAIT_MS=1_500;
const ALPACA_STALE_LOCK_MS=5*60_000;
function withReservationLock(base,fn,{name,guard,prefix}){
 if(!fs.existsSync(base)||!fs.statSync(base).isDirectory())throw guard(Date.now()+60_000,`${prefix}_BASE_UNAVAILABLE`);
 const lock=path.join(base,name);
 const until=Date.now()+ALPACA_LOCK_WAIT_MS;
 const sleeper=new Int32Array(new SharedArrayBuffer(4));
 const ownerFile=path.join(lock,'owner.json');
 const recoverDeadOwner=()=>{
  // Serialize reapers, then re-read the owner. Two reapers must not rename a
  // freshly acquired directory after one has already quarantined a dead owner.
  const recovery=`${lock}.recovery`;
  try{fs.mkdirSync(recovery);}catch{return false;}
  try{return recoverUnderGuard();}finally{try{fs.rmdirSync(recovery);}catch{}}
 };
 const recoverUnderGuard=()=>{
  // Never touch the Core lock. Only reclaim this exact quota directory after
  // proving that its owner PID has exited and it is older than five minutes.
  let owner,metadata;
  try{
   metadata=fs.statSync(lock);
   if(!metadata.isDirectory()||Date.now()-metadata.mtimeMs<ALPACA_STALE_LOCK_MS)return false;
   owner=JSON.parse(fs.readFileSync(ownerFile,'utf8'));
   if(!Number.isSafeInteger(owner.pid)||owner.pid<=0||!Number.isSafeInteger(owner.startedAt)||
     Date.now()-owner.startedAt<ALPACA_STALE_LOCK_MS)return false;
  }catch{return false;}
  try{process.kill(owner.pid,0);return false;}
  catch(error){if(error.code!=='ESRCH')return false;}
  try{const names=fs.readdirSync(lock);if(names.length!==1||names[0]!=='owner.json')return false;}catch{return false;}
  const orphan=`${lock}.stale-${process.pid}-${randomUUID()}`;
  try{
   fs.renameSync(lock,orphan);
   // Quarantined directory is quota-owned and contains one bounded metadata
   // file. Unrelated files mean unexpected state: leave it for manual review.
   fs.unlinkSync(path.join(orphan,'owner.json'));
   fs.rmdirSync(orphan);
   return true;
  }catch{return false;}
 };
 for(;;){
  let created=false;
  try{
   fs.mkdirSync(lock);created=true;
   fs.writeFileSync(ownerFile,JSON.stringify({pid:process.pid,startedAt:Date.now()}),{flag:'wx'});
   break;
  }
  catch(error){
   if(created){try{fs.unlinkSync(ownerFile);}catch{}try{fs.rmdirSync(lock);}catch{}throw guard(Date.now()+60_000,`${prefix}_LOCK_OWNER_WRITE_FAILED`);}
   if(error.code!=='EEXIST')throw guard(Date.now()+60_000,`${prefix}_LOCK_UNAVAILABLE`);
   if(recoverDeadOwner())continue;
   if(Date.now()>=until)throw guard(Date.now()+60_000,`${prefix}_LOCK_BUSY`);
   Atomics.wait(sleeper,0,0,15);
  }
 }
 try{return fn();}finally{fs.unlinkSync(ownerFile);fs.rmdirSync(lock);}
}
function withGeneralQuotaLock(base,provider,fn){
 fs.mkdirSync(base,{recursive:true});
 const guard=(retryAt,reason)=>Object.assign(Error('PROVIDER_QUOTA_GUARD'),{
  code:'PROVIDER_QUOTA_GUARD',provider,retryAt,reason
 });
 return withReservationLock(base,fn,{name:'quota-ledger-reservation.lock',guard,prefix:'QUOTA_LEDGER'});
}

